// Build the lead record from the form submission.
const form = $('Lead Intake \u2014 Form Trigger').first().json;
const d = new Date();
const ref = 'LEAD-' + d.toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.floor(1000 + Math.random() * 9000);
return [{ json: {
  lead_ref: ref,
  name: String(form.lead_name || '').trim(),
  email: String(form.lead_email || '').trim().toLowerCase(),
  phone: String(form.lead_phone || '').trim(),
  service_interest: String(form.service_interest || '').trim(),
  message: String(form.message || '').trim(),
  received_at: d.toISOString(),
  stage: 'LEAD_RECEIVED',
  status: 'LEAD_RECEIVED',
}}];

// Duplicate check: any existing row with the same email counts as a duplicate.
const rec = $('Prepare Lead Record').first().json;
const email = String(rec.email || '').toLowerCase();
let is_duplicate = false;
if (email) {
  for (const item of $('Search Existing Leads').all()) {
    if (String(item.json.email || '').toLowerCase() === email) { is_duplicate = true; break; }
  }
}
return [{ json: { is_duplicate: is_duplicate } }];

