// Telegram alert for a freshly qualified lead, with the booking link and GHL contact link.
const rec = $('Prepare Lead Record').first().json;
const cfg = $('CONFIG \u2014 Pipeline Settings').first().json;
const q = $('AI Agent \u2014 Qualify Lead').first().json.output;
const contactId = $('GHL \u2014 Create Contact').first().json.contact.id;
const ghlUrl = `https://app.gohighlevel.com/v2/location/${cfg.ghl_location_id}/contacts/detail/${contactId}`;
return [{ json: { message:
`<b>\u2705 Qualified lead synced to GoHighLevel</b>\n<b>${rec.name}</b> \u2014 intent score <b>${q.intent_score}/100</b>\nService: ${rec.service_interest}\nPhone: ${rec.phone} | Email: ${rec.email}\n${q.summary}\n\n\uD83D\uDCC5 Book a call: ${cfg.booking_link}\n\uD83D\uDC64 GHL contact: ${ghlUrl}`
}}];

// Final Telegram summary of the lead run (any verdict).
const rec = $('Prepare Lead Record').first().json;
const isDup = $('Detect Duplicate').first().json.is_duplicate;
let line;
if (isDup) {
  line = `Status: <b>DISCARDED</b> (duplicate submission \u2014 skipped AI scoring)`;
} else {
  const q = $('AI Agent \u2014 Qualify Lead').first().json.output;
  const st = q.verdict === 'qualified' ? 'QUALIFIED' : (q.verdict === 'nurture' ? 'NURTURED' : 'DISCARDED');
  line = `Verdict: <b>${q.verdict}</b> | Score: <b>${q.intent_score}/100</b> | Status: <b>${st}</b>\n${q.summary}`;
}
return [{ json: { message:
`<b>\uD83C\uDFAF New lead processed</b>\n<b>${rec.name}</b> (${rec.lead_ref})\nService: ${rec.service_interest} | Phone: ${rec.phone} | Email: ${rec.email}\n${line}`
}}];
